INSERT INTO restaurants (id, name, description, cuisine, eta, tone, is_open, image_url) VALUES ('burger-brasa', 'Burger Brasa', 'Hambúrgueres artesanais grelhados na brasa com pão brioche amanteigado e queijos nobres.', 'Hambúrgueres', '25–40 min', 'bg-amber-100 text-amber-800', 1, 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=600&auto=format&fit=crop&q=80');
INSERT INTO restaurants (id, name, description, cuisine, eta, tone, is_open, image_url) VALUES ('pizzaria-forno-lenha', 'Pizzaria Forno a Lenha', 'Pizzas artesanais napolitanas de fermentação natural assadas em forno à lenha tradicional.', 'Pizzas', '35–50 min', 'bg-brand-100 text-brand-700', 1, 'https://images.unsplash.com/photo-1513104890138-7c749659a591?w=600&auto=format&fit=crop&q=80');
INSERT INTO restaurants (id, name, description, cuisine, eta, tone, is_open, image_url) VALUES ('sushi-kaze', 'Sushi Kaze', 'Autêntica culinária japonesa com cortes nobres de salmão, atum fresco e combinados especiais.', 'Japonesa', '40–55 min', 'bg-sky-100 text-sky-800', 1, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=600&auto=format&fit=crop&q=80');
INSERT INTO restaurants (id, name, description, cuisine, eta, tone, is_open, image_url) VALUES ('cantina-da-nonna', 'Cantina da Nonna', 'Massas frescas artesanais preparadas diariamente com molhos rústicos e queijo parmesão ralado na hora.', 'Massas', '30–45 min', 'bg-emerald-100 text-emerald-800', 1, 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?w=600&auto=format&fit=crop&q=80');
INSERT INTO restaurants (id, name, description, cuisine, eta, tone, is_open, image_url) VALUES ('acai-tropical', 'Açaí Tropical', 'Açaí puro do Pará batido na consistência perfeita, smoothies naturais e bowls energéticos.', 'Açaí e sobremesas', '15–30 min', 'bg-violet-100 text-violet-800', 1, 'https://images.unsplash.com/photo-1590080875515-8a3a8dc5735e?w=600&auto=format&fit=crop&q=80');
INSERT INTO restaurants (id, name, description, cuisine, eta, tone, is_open, image_url) VALUES ('padaria-esquina', 'Padaria da Esquina', 'Pães quentinhos assados a cada hora, cafés especiais moídos na hora e doces artesanais.', 'Padaria e café', '20–35 min', 'bg-stone-200 text-stone-700', 1, 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=600&auto=format&fit=crop&q=80');
INSERT INTO products (id, restaurant_id, name, description, unit_price, category, available, image_url) VALUES ('prod-bb-1', 'burger-brasa', 'Burger Brasa Bacon', 'Pão brioche, hambúrguer 180g na brasa, queijo cheddar inglês derretido, tiras crocantes de bacon e maionese defumada.', 34.9, 'Hambúrgueres', 1, 'https://images.unsplash.com/photo-1553979459-d2229ba7433b?w=400&auto=format&fit=crop&q=80');
